"THE PROJECTED-MANY SALVAGE (2026-07-16, ported on Samuel's word: fail-2's second and last genuine canon delta joins its already-salvaged family). constraints:scoped_exclusion_projected_many composes one projected-exclusion checker per spec (a spec is popname, incoming-side sequence, stored-side sequence; the built checker answers the intersection of the two projections, empty when the exclusion holds) and flattens their verdicts: many role sequences, one violation surface. The enforcement wiring is LIVE: the oracle emits state:exclusions (scope lists; a subtype-meta scope names the child extent), cmd:excl_viols answers all pairwise projected intersections over a cell store, create carries the state's third slot to the answer, and the answer's store is the P2 pairs themselves — derived targets included, so ENTITY-EXTENT scopes enforce too (the state's rules derive the extents from the merged population). law:exclusion holds the composed store's real surface and both refuse/commit gates, fact-scope and derived-extent.",

