       S4(A("COMP"), S2(A("INSERT"), A("csdp:keep_mandatory_pos")), A("theta:append_phi"),
          S3(A("COMP"), A("distr"),
             S3(A("CONS"),
                S3(A("COMP"), A("theta:iota"),
                   S3(A("COMP"), A("length"), S3(A("COMP"), N(2), N(1)))),
                A("id")))),
