DEF("csdp",
    S8(A("COMP"), A("csdp:s7"), A("csdp:s6"), A("csdp:s5"), A("csdp:s4"),
       A("csdp:s3"), A("csdp:s2"), A("csdp:s1"))),

"RMAP AS CANON, THE STORE FORM (2026-07-15, the join-table collapse; supersedes the first table-map form — rmap:rule1/rule2/table_for/absorb_pair are replaced by the store and schema emitters below). rmap answers A STORE: a sequence of cells, each ⟨CELL, name, rows⟩ (Backus 13.3.4 — a cell is a CELL,name,contents triple so cells are distinguishable from pairs; 14.3 — the AST state D IS a sequence of cells; 14.7 — a cell in one store may contain another entire store, which is tenancy). The paper's own sentence is emitted literally: RMAP assigns each entity its own cell, the 3NF row of facts depending on its key — each rule-2 absorption group (fact types whose narrowest uniqueness constraint is a single role) becomes ONE ENTITY CELL whose contents are the wide rows ⟨keyval, slot…⟩, one slot per absorbed fact type — a PRESENT slot is the 1-sequence of the member's nonkey values (so a present unary, whose nonkey value sequence is itself phi, stays distinguishable), phi marks absence (optionality IS the empty sequence; a compound member contributes its nonkey sequence as one compound slot). Each rule-1 fact type (no single-role key: spanning or compound) becomes ONE RELATION CELL, contents its rows CURRIED by rmap:nest (THE CURRYING below) — the named relations are the cells themselves (paper 5.2), so a table is not a peer artifact of the store, it is fetch: Backus's up-arrow-n (13.3.4), which under rho is Codd's restriction on the name component followed by projection onto the contents (theta-restriction, codd72 2.3.5, constants entering as literal relations; adequacy of theta1, codd70 2.2). Backus's fetch and Codd's restrict-then-project are the same operator, and Church closes it: set membership is function application, a row is a tuple applied to selectors (numbers ARE its projections — apply:⟨pos,row⟩), and the store itself is the function name→contents whose graph is the cell relation. The 51 SQL join tables are that one relation head-lifted; their number is a fact about the projection surface, not about the store. rmap:schema answers the same content as descriptors ⟨name, players, ucs, mands, pop⟩ — output type = input type, so the algebra is closed and the fixpoint law (re-classifying the emitted schema reproduces its keys and separations) is canon-evaluable; csdp consumes what rmap emits (Halpin's step 1 verbalizes FROM wide output reports, and csdp:s4's induction rediscovers a wide cell's single-role key from its rows).",

DEF("rmap:arity", S3(A("COMP"), A("length"), N(2))),

DEF("rmap:pick_shorter",
    S4(A("COND"),
       S3(A("COMP"), A("le"),
          S3(A("CONS"), S3(A("COMP"), A("length"), N(1)), S3(A("COMP"), A("length"), N(2)))),
       N(1), N(2))),

DEF("rmap:min_uc",
    S3(A("COMP"), S2(A("INSERT"), A("rmap:pick_shorter")), N(3))),

DEF("rmap:functionalp",
    S3(A("COMP"), A("eq"),
       S3(A("CONS"), S3(A("COMP"), A("length"), A("rmap:min_uc")), S2(A("CONST"), N(1))))),

DEF("rmap:keypos",
    S3(A("COMP"), N(1), A("rmap:min_uc"))),

DEF("rmap:keyplayer",
    S3(A("COMP"), A("apply"),
       S3(A("CONS"), A("rmap:keypos"), N(2)))),

DEF("rmap:keep_functional",
    S4(A("COND"), S3(A("COMP"), A("rmap:functionalp"), N(1)), A("apndl"), N(2))),

DEF("rmap:keep_spanning",
    S4(A("COND"),
       S4(A("COMP"), A("not"), A("rmap:functionalp"), N(1)),
       A("apndl"), N(2))),

DEF("rmap:functionals",
    S3(A("COMP"), S2(A("INSERT"), A("rmap:keep_functional")), A("theta:append_phi"))),

DEF("rmap:spannings",
    S3(A("COMP"), S2(A("INSERT"), A("rmap:keep_spanning")), A("theta:append_phi"))),

DEF("rmap:keep_nonkey",
    S4(A("COND"),
       S3(A("COMP"), A("not"), S3(A("COMP"), A("eq"), N(1))),
       S3(A("COMP"), A("apndl"), S3(A("CONS"), S3(A("COMP"), N(1), N(1)), N(2))),
       N(2))),

DEF("rmap:nonkey_positions",
    S4(A("COMP"), S2(A("INSERT"), A("rmap:keep_nonkey")), A("theta:append_phi"),
       S3(A("COMP"), A("distr"),
          S3(A("CONS"),
             S3(A("COMP"), A("theta:iota"), A("rmap:arity")),
             A("rmap:keypos"))))),

DEF("rmap:nonkey_players",
    S3(A("COMP"), S2(A("ALPHA"), A("apply")),
       S3(A("COMP"), A("distr"),
          S3(A("CONS"), A("rmap:nonkey_positions"), N(2))))),

DEF("rmap:member_pairs",
    S3(A("COMP"),
       S2(A("ALPHA"),
          S3(A("CONS"),
             S3(A("COMP"), A("apply"),
                S3(A("CONS"), S3(A("COMP"), N(1), N(2)), N(1))),
             S3(A("COMP"), S2(A("ALPHA"), A("apply")),
                S3(A("COMP"), A("distr"),
                   S3(A("CONS"), S3(A("COMP"), N(2), N(2)), N(1)))))),
       S3(A("COMP"), A("distr"),
          S3(A("CONS"), N(5),
             S3(A("CONS"), A("rmap:keypos"), A("rmap:nonkey_positions")))))),

DEF("rmap:lookup0",
    S4(A("COND"),
       S3(A("COMP"), A("null"), A("csdp:matches")),
       S2(A("CONST"), PHI()),
       S3(A("COMP"), S2(A("CONS"), S3(A("COMP"), N(2), N(1))), A("csdp:matches")))),

DEF("rmap:slot",
    S3(A("COMP"), A("rmap:lookup0"),
       S3(A("CONS"), N(2), S3(A("COMP"), A("rmap:member_pairs"), N(1))))),

DEF("rmap:wide_row",
    S3(A("COMP"), A("apndl"),
       S3(A("CONS"), N(1),
          S3(A("COMP"), S2(A("ALPHA"), A("rmap:slot")),
             S3(A("COMP"), A("distr"), S3(A("CONS"), N(2), N(1))))))),

DEF("rmap:keyvals",
    S4(A("COMP"), A("theta:dedup"), A("theta:flatten"),
       S2(A("ALPHA"), S3(A("COMP"), S2(A("ALPHA"), N(1)), A("rmap:member_pairs"))))),

DEF("rmap:keep_of_key",
    S4(A("COND"),
       S3(A("COMP"), A("eq"),
          S3(A("CONS"), S3(A("COMP"), N(1), N(1)),
             S3(A("COMP"), A("rmap:keyplayer"), S3(A("COMP"), N(2), N(1))))),
       S3(A("COMP"), A("apndl"), S3(A("CONS"), S3(A("COMP"), N(2), N(1)), N(2))),
       N(2))),

DEF("rmap:members_of",
    S4(A("COMP"), S2(A("INSERT"), A("rmap:keep_of_key")), A("theta:append_phi"), A("distl"))),

DEF("rmap:group_for",
    S6(A("CONS"),
       N(1),
       S3(A("COMP"), A("apndl"),
          S3(A("CONS"), N(1),
             S3(A("COMP"), S2(A("ALPHA"), A("rmap:nonkey_players")), A("rmap:members_of")))),
       S2(A("CONST"), S1(S1(N(1)))),
       S2(A("CONST"), PHI()),
       S3(A("COMP"), S2(A("ALPHA"), A("rmap:wide_row")),
          S3(A("COMP"), A("distr"),
             S3(A("CONS"),
                S3(A("COMP"), A("rmap:keyvals"), A("rmap:members_of")),
                A("rmap:members_of")))))),

DEF("rmap:keys",
    S3(A("COMP"), A("theta:dedup"), S2(A("ALPHA"), A("rmap:keyplayer")))),

DEF("rmap:groups",
    S3(A("COMP"), S2(A("ALPHA"), A("rmap:group_for")),
       S3(A("COMP"), A("distr"), S3(A("CONS"), A("rmap:keys"), A("id"))))),

DEF("rmap:schema",
    S3(A("CONS"),
       S3(A("COMP"), A("rmap:groups"), S3(A("COMP"), A("rmap:functionals"), N(1))),
       S3(A("COMP"), A("rmap:spannings"), N(1)))),

"THE CURRYING (2026-07-16 ruling: arest RMAP and NORMA RMAP must agree; the higher-arity fact types are higher-arity functions, and this is lambda calculus, so curried functions are just single-parameter functions that are chained). A relation cell's contents is rmap:nest of its rows: one store level per role, each level a sequence of CELL,value,contents cells keyed by that role's value, the last level the image sequence — the fact type's extension serialized as its curry, which makes the extension the fact type's DEFINITION (definition by extension, the third kind of cell contents beside a compiled FFP body and a registered marker — Def 9's origins as contents kinds), homed where DEFS homes every definition: under the function's own name (Backus 13.3.5). Applying the fact-type-as-function IS ast:Fetch, level by level: fetch of the relation cell then fetch of a key value answers that key's image, so application = fetch = Codd restriction, chained one parameter at a time, and a functional level is the level whose images are 1-sequences — rule 2's wide row (id then slot then 1-sequence value) was ALREADY this curry, so rule 1 and rule 2 emit one shape that differs only in fan-out. The flat table is the derived presentation rmap:unnest (Codd 1970 1.3: normal form is a storage discipline for flat arrays, explicitly eliminable and reversible; AST holds sequences natively, so the store keeps the curry and the view keeps Codd), and the agreement law holds the two RMAPs equal: classification and grouping compare as before over rmap:schema, and rmap:unnest of every emitted relation cell must reproduce the population rows exactly — nest and unnest are inverses on deduplicated rows, so nothing is lost that NORMA asserts.",

DEF("rmap:keep_row_of",
    S4(A("COND"),
       S3(A("COMP"), A("eq"),
          S3(A("CONS"), S3(A("COMP"), N(1), N(1)),
             S3(A("COMP"), N(1), S3(A("COMP"), N(2), N(1))))),
       S3(A("COMP"), A("apndl"), S3(A("CONS"), S3(A("COMP"), N(2), N(1)), N(2))),
       N(2))),

