"THE MANIFEST (2026-07-15, exec ruling 4: Def 9 / Cor 5 as canon). manifest:origins computes the enumerable boundary from the store itself: a definition's origin is 'compiled' exactly when its name is a cell of D, and every atom referenced in FUNCTIONAL POSITION that is not a cell name is 'registered' — the host-supplied surface (Eq 5's Filter on origin; Cor 5's enumerable boundary, executed as set arithmetic over the store). The walk is TOTAL, a conservative over-approximation: any atom in a tree may reach operator position at runtime through apply (a function's representation IS its datum — the apply-through-DEFS seams ride in CONST position), so every atom is a potential reference; the registered set is references minus definitions and therefore includes data atoms, which the boundary rows adjudicate — the readings declare which registered names are OPERATIONS, and the checker holds the rows within the computed set. Numeric atoms are selectors and ride along; name-consumers ignore them. impl needs no computation: Def 9's impl IS the cell's contents, definitionally present in the store. dom and cod are not derivable from trees (the base has no type inference); system:registered below is the SALVAGED rebuild manifest — the five boundary primitives with dom/cod transcribed from the quarry implementations — and resolution.md's boundary rows state the same facts as instance-fact verbalizations, the fixture the checker mu holds manifest:origins against.",

