"THE FIXPOINT AS CANON (2026-07-16 ruling: the performance optimizations belong in canon â object and fact type filtering, never the whole-population fixpoint). derive is the Command definition's lfp(F_S, P) evaluated SEMI-NAIVELY from birth: the loop state is pops-and-delta, and each round applies each rule only to what changed â a projection rule is linear (the delta of its source only, so a rule whose source gained nothing contributes phi), the chain join is bilinear (delta-G join full-H union full-G join delta-H â the delta predicates of the DatalogLB mapping paper), and fresh facts are the set-difference against the target's current population, so iteration reaches Lemma 1's least fixed point with every round bounded by the deltas. The scope discipline is Cor 6 made operational: which fact types a rule reads is data (the recipe names its sources), so evaluation fetches exactly those populations and no others â the recalculation a write forces is bounded to the cells the rules can reach, the scope the schema fixes. A rule is target-and-recipe; a recipe is proj (source, columns) or the chain join (G, H, columns; G.2 = H.1, relation composition â wider join shapes are the evaluator extension, mirroring csdp:s4's binary-core honesty). Recursive rules are ordinary rules: reaches from contained is the fixture law:derive holds as a known answer.",

