"THE RULES AS CANON (2026-07-16 ruling: the eval-gate is wrong — everything should be canon; only registered effects wait for hosts. Extended the same day: go ahead and fix the issues — the named recipe forms land). The recipe grammar closes over composition (a source slot is a population name or a sub-recipe; an entity population enters as a one-column source under the entity's own name, which is how a subtype-cast body reads through the one id space) and carries eight forms: proj (projection), flat (the nesting transformation inverted at derivation time: a nested attachment stores its objectified instance extensionally as the tuple itself in column one, Definition 4's identity with surrogates left at the boundary, and flat unfolds that column into its components, Codd 1970 1.3 run in reverse; linear delta), join (the chain, G.2 = H.1), joinon (join on listed position pairs — an empty list is the cross product), sel (restriction to a constant, Codd's literal relation), cmp (restriction by comparison between two columns — the inequality theta), minus (the anti-join mirror, stratified: the right side reads the settled store, never the delta), and count (the aggregate of Definition 7, a finite bag to one scalar — value-introducing, so settled-required like a minus right side). Deltas: proj/sel/cmp are linear, join/joinon bilinear (delta-G join full-H union full-G join delta-H — the DatalogLB delta predicates), minus is delta-left against settled-right, count recomputes from the settled source and converges by set-difference. EXECUTION IS STRATIFIED: derive:layers splits the rule set into layers — a rule is ready when its settled-required reads (minus rights, count sources) are not produced by any remaining rule, and the ready set then SHRINKS to its greatest fixed point so that no ready rule positively reads a target that stays behind (a reader lands with or after its feeder; mutually recursive positives share a layer and the per-layer semi-naive fixpoint handles them); an unstratifiable remainder collapses to one final layer, which law:finiteness refuses ever to reach. rules:metamodel is the metamodel's complete star-rule set as executable data (39 rules): the defined/terminal/rooted family, the effective-initial pair (declared initial, else the rooted fallback where no initial is declared — minus over a joinon), both Mealy edges, the status reaches closure including its two-column transitive joinon, the domain and derivation-rule closures, the dependency graph, the bridge casts and belongs-to family, Fact Type arity by count, Domain Change blocking (sel on Severity through the Resource cast) and validity (minus over blocking, a genuinely stratified rule), Failure succeeds Violation (the reified union that replaced the disjunctive consequent: caused-by, or temporally after by cmp over a cross), Transition occurred at Timestamp, the state-machine instance and occupancy rules, and the two re-entered audit-B sketches: Fact is in consequent Fact Type (the SS auto-fill restated over is-provided-by/produces/has-antecedent through the Fact is of Function cast) and Fact joins Fact (the transitivity sketch's positional prose finally in the fragment: chain-composability through fills/uses and reading positions two then one, distinct facts held by two cmp mirrors, irreflexive by construction). law:rules holds fourteen known answers (the derivation-rule chain derives its dependency graph and closure, and the closure's transitivity — the TR ring's theorem — is witnessed by execution: the chain of the derived reaches minus reaches is empty, non-vacuously) over one fixture; law:finiteness is Cor 6 executed with two negative fixtures (a minus cycle and a count cycle must both be refused). Named residue, canon-path: the temporal-latest occupancy fold is Prop 1's machine reconstruction, its own increment.",

