"THE INDUCTION AS CANON (2026-07-16 ruling: induce/abduce as a canon function). Codd 1970 2.3 names the act â the system might, over a period of time, make attempts to induce the redundancies, but such attempts would be fallible â and 1.5 names the target: strong redundancy, a relation with a projection derivable from other members. induce searches the design state for exactly those: for each populated binary target, candidate recipes by projection of a compatible source or by the chain join of two compatible sources, with GENERATION FILTERED BY DECLARED PLAYER SIGNATURES (state:declared) â the object and fact type filtering: only type-compatible sources are ever evaluated, and each candidate evaluates over exactly the populations its recipe names, never the whole P. Each candidate answers the tuple the standing judge already consumes â target, recipe, the coverage gate (observed minus derived is phi), the exactness gate (derived minus observed is phi; the complements are the explains-Fact and hidden-Fact readings of induction.md), and the evidence count as score â and system:induce_judge ranks the gated survivors: candidates plus a judge, never silent adoption. Adopting a ranked candidate as a derivation rule is a modeling judgment at the registered boundary (like csdp:accept_judgment), and its target then leaves the stored schema per Codd 1.5 â induce finds the markers the derived-exclusion doctrine consumes. Nonrecursive candidates only; recursive rules are derive's business. abduce is the same pipeline named for its direction of use. law:induce re-verifies every ranked candidate: its recipe, re-evaluated, reproduces the target population exactly. The search space carries the joinon orientations beside the chain: same-first (converging) and same-last (diverging) joins, each in both output orders, sig-filtered like everything else; the mirrored-chain orientation is excluded as a respelling, and a diverging self-join (coparent from parent) is the witness a chain can never produce. Beyond binaries, a data-driven entry table (join pair plus output columns over the concatenated signature) carries the ternary-by-binary orientations ternary-first (the binary-first shape is the mirror respelling across the swapped pair), targets still binary, signatures computed once per source pair and the arity shape picking its sub-table; the in-law fixture (ternary parentIn joined to marriedTo at the shared child, family column existential) is the witness no binary-source shape can produce. law:induce's first arm re-verifies COVERAGE of every ranked candidate — ranked hypotheses may carry hidden rows by design, and exactness is pinned by the fixture legs. The space also carries ternary TARGETS (three-column outputs over binary joins, the H-side join column excluded as redundant but the G-side available — a ternary output spans both sources where a binary pair touching the join column is always projection-reachable), ternary-by-ternary joins (i<=j, the swapped pair carries the mirror), and the symmetric closure beside the transitive one (Tarski's closure family: base plus its own swap). Witnesses: chain3 (the one three-column join spelling), sameKid (the diverging ternary self-join, both spellings), friends-from-likes (the symmetric closure, exactly one).",

