"THE NAVIGATION MAP AS EMITTED VIEW (2026-07-16 ruling: the links section generates it â a navmap can be generated from rmap, and it serves GUI, console, and server alike). MonoCross kept a hand-registered NavigationMap of pattern,controller pairs and proved the shape by binding ONE map to GUI containers, a console container, and an HTTP server container; the paper names each part: a pattern is a fact type (literal segments are constants, parameter segments open roles â here a literal is an atom and a parameter the 1-sequence of its player), matching is theta-restriction (eq composed with selectors and constants), binding is projection, dispatch is metacomposition Eq 1, and Thm 2 makes the map's content a generated projection: links(e) = nav(e) union transitions(status(e)), complete and current, no hand-written links. nav:map derives the pattern set from rmap:schema exactly as rmap derives the application schema â the emission doctrine again: an entity group answers its collection pattern and its item pattern; a separated fact type answers one pattern per curry prefix (every prefix is a valid fetch, so the pattern tree IS the trie and the address space IS the store â navigation needs no separate query language); nav:links is Thm 2's equation, nav:peers reading the fact types an entity plays from the extension cells and the transitions leg supplied by system:view_menu. One map, every container: a browser, a console, and a server differ only in registered render functions (vary DEFS, not the logic), which is what MonoCross demonstrated and the platform-binding paragraph states. law:navmap holds the generation: every pattern head names a cell of the emitted store and every cell heads a pattern family â no pattern is registered by hand. nav:form is the view-position mechanism (2026-07-17 ruling: the position of a property is settable data, the core mechanism for mapping a data type to a list or a form): an entity's item view is its absorbed properties ordered by the Fact Type has Declaration Order POPULATION — the oracle fills it from source order and an explicit row SETS it, so authored position beats declaration position; 999 marks the unpositioned tail. The hyphen-bound role qualifiers ride the intersection as state:qualifiers (one mechanism: NORMA's reading text and the carrier surface agree), supplying the rendered labels.",

