"THE LAWS AS CANON (2026-07-16 ruling: write the laws as canon DEFs). A Law's Implementation is the check itself (Def 9), so the gates are definitions the mu applies, never host code â the js runner's deletion taught that a law written in a host IS the meaning-location failure. Every law takes THE COMPOSED STORE (the sequence of CELL,name, contents cells the vocabulary accumulates while the canon and the carriers register â Backus: D is first-class, so the store reads itself) and answers T or F: law:fts and law:norma unfold the carriers shape-driven through the canon's own flatten (chunks of nine until the leaf shapes: descriptor, row, pair, atom); law:rmap_idempotence re-classifies the emitted schema; law:table_is_fetch holds fetch equal to contents and every curried application equal to restriction-then-projection; law:schema_match holds the one-table form against NORMA (exactly the Function table, every separation accounted as an absorbed column group â slug and strip_prefix are the REGISTERED boundary rows of resolution.md doing the lexical work); law:origin_boundary holds manifest:origins over the canon cells to compiled = DEFs and hand rows inside computed-registered; law:population_consistency re-induces every declared single-role key from the attributed rows (csdp:s4 run backwards); law:currying holds nest and unnest inverse on every spanning population; law:emission holds every emitted wide-row slot equal to a fetch chain through ast:File. law:report names each verdict — the laws' names ARE their rows, held by whichever host execs the composed bytes (the constitution file is retired: a law that executes needs no restatement, a host that holds every law needs no assignment table, and process rules are not domain facts); law:all is their conjunction.",

