"The algebra of programs as canon (Backus 1978 Turing lecture, 12.4): program-improving identities are equations over terms, so they are facts, so they live here and never in a host. rewrite:step is one TOTAL structural pass — selector-of-CONS cancellation (i o [f1..fn] = fi, applied only when the selector matches exactly one index; an out-of-range selector keeps its runtime death), ALPHA fusion (af o ag = a(f o g)), COMP flattening, id elimination — and rewrite:normalize is its fixpoint. CONST payloads are data and pass untouched, as do unknown heads and arities (recipe terms and die-stub positions keep their exact shape: deaths happen only when taken). Strictness proviso: cancellation skips the evaluation of dropped CONS legs, so death-timing on inputs where a dropped leg dies is not preserved — the certifier holds observational byte-identity over the composed stores, where every evaluated leg is total. law:rewrite_soundness pins structure-preserving cases, checks apply-equality on rewritten witnesses, and asserts idempotence. Consumers: any host wanting the algebra applies rewrite:normalize to DEF bodies before evaluation or codegen (muc does exactly this); interpretive stations stay unrewritten and are the differential control.",

